  10     const { project, updateProject } = useBuilderStore();
  11 
  12     const section = useMemo(() => project?.getSection(itemKey), [project, itemKey]);
  13 
  14     const currentSelection = useMemo(() => {
  15         return section?.context || { sections: {}, externalContext: {} };
  16     }, [section?.context]);
  17 
  18     const reportSections = useMemo(() => {
  19         if (!project?.sections) return [];
  20         return project.sections
  21             .filter(s => s.id !== itemKey)
  22             .map(s => ({ id: s.id, title: s.title }));
  23     }, [project?.sections, itemKey]);
  24     
  25     const sectionsContent = useMemo(() => {
  26         if (!project?.sections) return {};
  27         return project.sections.reduce((acc, section) => {
  28             acc[section.id] = section.content || '';
  29             return acc;
  30         }, {} as Record<string, string>);
  31     }, [project?.sections]);
  32 
  33 
  34     const handleContextChange = useCallback((
  35         sectionId: string,
  36         type: 'sections' | 'externalContext',
  37         subKey: string,
  38         value: ExternalContextType | false
  39     ) => {
  40         updateProject(p => p.updateSection(sectionId, (sec) => {
  41             const newContext = { ...sec.context };
  42             const newDict = { ...(newContext[type] || {}) };
  43             
  44             if (value === false) {
  45                 delete newDict[subKey];
  46             } else {
  47                 newDict[subKey] = value;
  48             }
  49             
  50             newContext[type] = newDict;
  51             return sec.with({ context: newContext });
  52         }));
  53     }, [updateProject]);
  54 
  55     return {
  56         t,
  57         reportSections,
  58         handleContextChange,
  59         currentSelection,
  60         sections: sectionsContent,
  61         externalContext: project?.externalContext || [],
  62     };
  63 }
