  33         },
  34         // Optimistic update
  35         onMutate: async (newFeatureData) => {
  36             await queryClient.cancelQueries({ queryKey: featureKeys.lists() });
  37             const previousFeatures = queryClient.getQueryData<Feature[]>(featureKeys.lists());
  38 
  39             queryClient.setQueryData<Feature[]>(featureKeys.lists(), old =>
  40                 old?.map(feature =>
  41                     feature.id === newFeatureData.featureId
  42                         ? { ...feature, ...newFeatureData.payload }
  43                         : feature
  44                 ) || []
  45             );
  46 
  47             return { previousFeatures };
  48         },
