  26     const projectUpdates: Partial<ProjectProperties> = {
  27       content: newContent,
  28     };
  29 
  30     if (template.projectType) projectUpdates.projectType = template.projectType;
  31     if (template.specialization) projectUpdates.specialization = template.specialization;
