  20 export function useNotifications() {
  21     const { firebaseUser } = useAuth();
  22     const [notifications, setNotifications] = useState<Notification[]>([]);
  23 
  24     useEffect(() => {
  25         if (!firebaseUser?.uid) {
  26             setNotifications([]);
  27             return;
  28         }
  29 
  30         const notificationsRef = ref(rtdb, `notifications/${firebaseUser.uid}`);
  31 
  32         const listener = onValue(notificationsRef, (snapshot) => {
  33             const data = snapshot.val();
  34             if (data) {
  35                 const notificationsList = Object.keys(data).map(key => ({
  36                     id: key,
  37                     ...data[key]
  38                 })).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()); // Sort newest first
  39                 setNotifications(notificationsList);
  40             } else {
  41                 setNotifications([]);
  42             }
  43         });
  44 
  45         // Cleanup listener on component unmount
  46         return () => off(notificationsRef, 'value', listener);
