  23 /**
  24  * Higher-order function to wrap API route handlers with authentication checks.
  25  * @param handler - The API route handler function.
  26  * @param options - Options to specify authentication requirements (e.g., requireAdmin).
  27  * @returns A Next.js API route handler.
  28  */
  29 export const withAuth = (handler: ApiHandler, options: ApiHandlerOptions = {}) => {
  30   return async (request: NextRequest, { params }: { params: Promise<{ [key: string]: string }> }) => {
  31     try {
  32       const authorization = request.headers.get('Authorization');
  33       if (!authorization?.startsWith('Bearer ')) {
  34         return handleApiError({ message: 'Unauthorized: Missing token' }, 401);
  35       }
  36       const token = authorization.substring(7);
  37       const decodedToken = await adminAuth.verifyIdToken(token, true);
  38 
  39       if (!decodedToken || !decodedToken.uid) {
  40         return handleApiError({ message: 'Unauthorized: Invalid token' }, 401);
  41       }
  42 
  43       const controller = container.resolve(UserController);
  44       const user = await controller.getUser(decodedToken.uid);
  45       
  46       if (!user) {
  47         return handleApiError({ message: 'Forbidden: User profile not found' }, 403);
  48       }
  49 
  50       if (options.requireAdmin && user.role !== 'admin') {
  51         return handleApiError({ message: 'Forbidden: Admin access required' }, 403);
  52       }
  53 
  54       const awaitedParams = await params;
  55       return handler({ request, user, token, params: awaitedParams });
  56     } catch (error: any) {
  57       // All errors, including auth errors, are now piped through the central handler
  58       return handleApiError(error);
  59     }
  60   };
  61 };
  62 
  63 /**
  64  * Standardized error handler for API routes.
  65  * @param error - The error object.
  66  * @param defaultStatus - The HTTP status code to use if none is found on the error.
  67  * @returns A NextResponse object with a standardized error format.
  68  */
  69 export const handleApiError = (error: any, defaultStatus = 500) => {
  70   console.error("API Route Error:", error);
  71 
  72   // 1. Handle Zod validation errors specifically
  73   if (error instanceof ZodError) {
  74     return NextResponse.json({ message: 'Validation failed', errors: error.flatten().fieldErrors }, { status: 400 });
  75   }
  76 
  77   // 2. Attempt to handle as a Firebase error
  78   const firebaseError = handleFirebaseError(error);
  79   if (firebaseError instanceof CustomFirebaseError) {
  80     let status = 400; // Default for many auth errors
  81     if (firebaseError.code.includes('not-found')) status = 404;
  82     if (firebaseError.code.includes('permission-denied')) status = 403;
  83     if (firebaseError.code.includes('already-exists')) status = 409;
  84     if (firebaseError.code.includes('unauthenticated') || firebaseError.code.includes('token-expired')) status = 401;
  85 
  86     return NextResponse.json({ message: firebaseError.message, code: firebaseError.code }, { status });
  87   }
  88 
  89   // 3. Handle custom thrown errors (e.g., from our own logic)
  90   if (error.status && error.message) {
  91     return NextResponse.json({ message: error.message }, { status: error.status });
  92   }
  93 
  94   // 4. Fallback for generic/unexpected errors
  95   const message = error.message || 'An unexpected server error occurred.';
  96   const status = error.status || defaultStatus;
  97 
  98   return NextResponse.json({ message }, { status });
  99 };
