  12 /**
  13  * Parses a markdown string and converts it into a structured array of Chapter and Section objects.
  14  * This function is now more intelligent, handling hierarchy and preserving existing IDs and properties.
  15  *
  16  * @param markdown The raw markdown string to parse.
  17  * @param existingContent The current project content to preserve IDs and properties.
  18  * @param isToc Only parse structure (headings, lists), ignore other content.
  19  * @returns An array of Chapter and Section objects.
  20  */
  21 export function parseMarkdownToContent(markdown: string, existingContent: ProjectContent, isToc: boolean = false): ProjectContent {
  22   const ast = unified().use(remarkParse).use(remarkGfm).parse(markdown) as MdastRoot;
  23   const newContent: (Chapter | Section)[] = [];
  24   let currentChapter: Chapter | null = null;
  25   let currentSection: Section | null = null;
  26   let accumulatedContent: RootContent[] = [];
  27   const usedIds = new Set<string>(); // Keep track of used IDs to avoid duplicates
  28 
  29   const findExistingItem = <T extends Chapter | Section>(title: string, collection: ProjectContent, constructor: { new(props: any): T }): T | undefined => {
  30     for (const item of collection) {
  31         if (item instanceof constructor && item.title === title && !usedIds.has(item.id)) {
  32             return item as T;
  33         }
  34         if (item instanceof Chapter) {
  35             const foundInSection = item.sections.find(s => s.title === title && !usedIds.has(s.id));
  36             if (foundInSection && constructor === Section) {
  37                 return foundInSection as T;
  38             }
  39         }
  40     }
  41     return undefined;
  42   };
  43 
  44   const flushSection = () => {
  45     if (currentSection) {
  46       const sectionMarkdown = isToc ? (currentSection.content || '') : unified().use(remarkGfm).use(remarkStringify).stringify({ type: 'root', children: accumulatedContent }).trim();
  47       
  48       currentSection = currentSection.with({ content: sectionMarkdown });
  49 
  50       if (currentChapter) {
  51         // addSection is immutable and returns a new Chapter instance
  52         currentChapter = currentChapter.addSection(currentSection);
  53       } else {
  54         newContent.push(currentSection);
  55       }
  56     }
  57     accumulatedContent = [];
  58   };
  59 
  60   const flushChapter = () => {
  61     flushSection();
  62     if (currentChapter) {
  63       newContent.push(currentChapter);
  64     }
  65     currentChapter = null;
  66   };
  67 
  68   // Process all nodes in the AST
  69   for (const node of ast.children) {
  70     if (node.type === 'heading') {
  71       const title = getNodeText(node).trim();
  72       if (node.depth === 1) { // Chapter
  73         flushChapter();
  74         const existingChapter = findExistingItem(title, existingContent, Chapter);
  75         currentChapter = new Chapter({ 
  76           id: existingChapter?.id, 
  77           title: title, 
  78           sections: [] // CRITICAL FIX: Always start with empty sections
  79         });
  80         if (existingChapter) usedIds.add(existingChapter.id);
  81         currentSection = null; // Reset section when a new chapter starts
  82       } else { // Section
  83         flushSection();
  84         const existingSection = findExistingItem(title, existingContent, Section);
  85         currentSection = new Section({
  86             id: existingSection?.id,
  87             title: title,
  88             type: existingSection?.type || 'report',
  89             content: existingSection?.content,
  90             controls: existingSection?.controls,
  91             prompt: existingSection?.prompt,
  92             rules: existingSection?.rules ? [...existingSection.rules] : [],
