 249   public updateChapter(id: string, updater: (c: Chapter) => Chapter): Project {
 250     const idx = this.content.findIndex(c => c.id === id && c instanceof Chapter);
 251     if (idx === -1) return this;
 252 
 253     const newContent = [...this.content];
 254     const originalChapter = newContent[idx] as Chapter;
 255     newContent[idx] = updater(originalChapter);
 256 
 257     return this.with({ content: newContent });
 258   }
