  10   setLocale: (locale: Locale) => void;
  11   t: (key: string, variables?: Record<string, any>) => string;
  12 }
  13 
  14 const translations: Record<Locale, Record<string, any>> = { en, ar };
  15 
  16 const LocalizationContext = createContext<LocalizationContextType | undefined>(undefined);
  17 
  18 export const LocalizationProvider = ({ children }: { children: ReactNode }) => {
  19   const [locale, setLocaleState] = useState<Locale>('en');
  20 
  21   useEffect(() => {
  22     const savedLocale = localStorage.getItem('locale') as Locale;
  23     if (savedLocale && ['en', 'ar'].includes(savedLocale)) {
  24       setLocaleState(savedLocale);
  25     }
  26   }, []);
  27 
  28   const setLocale = (newLocale: Locale) => {
  29     setLocaleState(newLocale);
  30     localStorage.setItem('locale', newLocale);
  31   };
  32 
  33   const t = (key: string, variables?: Record<string, any>): string => {
  34     const keys = key.split('.');
  35 
  36     const findTranslation = (localeToTry: Locale): string | undefined => {
  37       let result: any = translations[localeToTry];
  38       for (const k of keys) {
  39         result = result?.[k];
  40         if (result === undefined) return undefined;
  41       }
  42       return typeof result === 'string' ? result : undefined;
  43     };
  44 
  45     // Attempt to find translation, then fallback, finally default to key
  46     let translated: string = findTranslation(locale) || findTranslation('en') || key;
  47 
  48     // Interpolate variables if provided
  49     if (variables) {
  50       Object.keys(variables).forEach((varName) => {
  51         translated = translated.replace(`{${varName}}`, variables[varName]);
  52       });
  53     }
  54 
  55     return translated;
  56   };
  57 
  58   return (
  59     <LocalizationContext.Provider value={{ locale, setLocale, t }}>
  60       {children}
  61     </LocalizationContext.Provider>
  62   );
  63 };
  64 
  65 export const useLocalization = (): LocalizationContextType => {
  66   const context = useContext(LocalizationContext);
  67   if (context === undefined) {
  68     throw new Error('useLocalization must be used within a LocalizationProvider');
  69   }
  70   return context;
