  91             guidelines: existingSection?.guidelines ? [...existingSection.guidelines] : [],
  92             constraints: existingSection?.constraints ? [...existingSection.constraints] : [],
  93             behaviors: existingSection?.behaviors ? [...existingSection.behaviors] : [],
  94             context: existingSection?.context,
  95         });
  96         if (existingSection) usedIds.add(existingSection.id);
  97       }
  98     } else if (node.type === 'list' && currentChapter && isToc) {
  99         for (const listItem of node.children) {
 100             if (listItem.type === 'listItem') {
 101                 const sectionTitle = getNodeText(listItem).trim();
 102                 if (sectionTitle) {
 103                     flushSection();
 104                     const existingSection = findExistingItem(sectionTitle, existingContent, Section);
 105                     currentSection = new Section({
 106                         id: existingSection?.id,
 107                         title: sectionTitle,
 108                         type: 'report',
 109                         // Carry over other properties from existing if needed
 110                     });
 111                     if (existingSection) usedIds.add(existingSection.id);
 112                     flushSection();
 113                     currentSection = null;
 114                 }
 115             }
 116         }
 117     } else {
 118       if (currentSection) {
 119         accumulatedContent.push(node);
 120       }
 121     }
 122   }
 123 
 124   flushChapter();
 125 
 126   return newContent;
 127 }
