 182         const project = useBuilderStore.getState().project;
 183         if (!project || !firebaseUser) throw new Error("User or project not found.");
 184         
 185         const chapter = project.getChapter(chapterId);
 186         if (!chapter) throw new Error("Chapter not found.");
 187         
 188         const sectionsToBuild = chapter.sections.filter(s => sectionIds.includes(s.id));
 189         if (sectionsToBuild.length === 0) throw new Error('No sections selected in this chapter.');
 190 
 191         const token = await firebaseUser.getIdToken();
 192         const body = {
 193             chapterTitle: chapter.title,
 194             sectionInstructions: sectionsToBuild.map(s => ({
 195               title: s.title, 
 196               prompt: s.buildActionPrompt(), 
 197               guidelines: s.guidelines,
 198               instructionText: PromptBuilder.buildSectionPrompt(s, project), 
 199               context: '' // Context is handled at a higher level if needed, but here we scope it per section
 200             }))
 201         };
 202 
 203         const result = await writingToolApi<any, { markdownContent: string }>(`/api/writing-tools/generate-chapter`, { data: body, token });
 204         return { chapterId, content: result.markdownContent };
 205     },
 206     onSuccess: (data) => {
 207         updateProject(p => {
 208             // Re-parse the generated content for the whole chapter and update the sections within it
 209             const parsedContent = parseMarkdownToContent(data.content, p.content);
 210             const newChapter = parsedContent[0]; // Assuming one chapter was generated
 211             if (newChapter instanceof Chapter) {
 212                 // This replaces the old sections with newly generated ones
 213                 return p.updateChapter(data.chapterId, c => c.with({ sections: [...newChapter.sections] }));
 214             }
 215             return p;
 216         });
 217         refetchUser();
 218         toast({ title: 'Chapter Generated', description: 'The AI has generated the content for the chapter.' });
 219     },
 220     onError: (error: any) => toast({ title: 'Chapter Generation Error', description: error.message, variant: 'destructive' })
 221   });
