 226       if (!firebaseUser) throw new Error("User not found.");
 227       if (selectedSectionIds.size === 0) throw new Error('No sections were selected for generation.');
 228       
 229       for (const sectionId of selectedSectionIds) {
 230           // This will be slow as it runs sequentially.
