  19 export function parseMarkdownToContent(markdown: string, existingContent: ProjectContent, isToc: boolean = false): ProjectContent {
  20   const ast = unified().use(remarkParse).use(remarkGfm).parse(markdown) as MdastRoot;
  21   const newContent: (Chapter | Section)[] = [];
  22   let currentChapter: Chapter | null = null;
  23   let currentSection: Section | null = null;
  24   let accumulatedContent: RootContent[] = [];
  25   const usedIds = new Set<string>(); // Keep track of used IDs to avoid duplicates
  26 
  27   const findExistingItem = <T extends Chapter | Section>(title: string, collection: ProjectContent, constructor: { new(props: any): T }): T | undefined => {
  28     for (const item of collection) {
  29         if (item instanceof constructor && item.title === title && !usedIds.has(item.id)) {
  30             return item as T;
  31         }
  32         if (item instanceof Chapter) {
  33             const foundInSection = item.sections.find(s => s.title === title && !usedIds.has(s.id));
  34             if (foundInSection && constructor === Section) {
  35                 return foundInSection as T;
  36             }
  37         }
  38     }
  39     return undefined;
  40   };
  41 
  42   const flushSection = () => {
  43     if (currentSection) {
  44       const sectionMarkdown = isToc ? (currentSection.content || '') : unified().use(remarkGfm).use(remarkStringify).stringify({ type: 'root', children: accumulatedContent }).trim();
  45       
  46       currentSection = currentSection.with({ content: sectionMarkdown });
  47 
  48       if (currentChapter) {
  49         // addSection is immutable and returns a new Chapter instance
  50         currentChapter = currentChapter.addSection(currentSection);
  51       } else {
  52         newContent.push(currentSection);
  53       }
  54     }
  55     accumulatedContent = [];
  56   };
  57 
  58   const flushChapter = () => {
  59     flushSection();
  60     if (currentChapter) {
  61       newContent.push(currentChapter);
  62     }
  63     currentChapter = null;
  64   };
  65 
  66   // Process all nodes in the AST
  67   for (const node of ast.children) {
  68     if (node.type === 'heading') {
  69       const title = getNodeText(node).trim();
  70       if (node.depth === 1) { // Chapter
  71         flushChapter();
  72         const existingChapter = findExistingItem(title, existingContent, Chapter);
  73         currentChapter = new Chapter({ 
  74           id: existingChapter?.id, 
  75           title: title, 
  76           sections: [] // CRITICAL FIX: Always start with empty sections
  77         });
  78         if (existingChapter) usedIds.add(existingChapter.id);
  79         currentSection = null; // Reset section when a new chapter starts
  80       } else { // Section
  81         flushSection();
  82         const existingSection = findExistingItem(title, existingContent, Section);
  83         currentSection = new Section({
  84             id: existingSection?.id,
  85             title: title,
  86             type: existingSection?.type || 'report',
  87             content: existingSection?.content,
  88             controls: existingSection?.controls,
  89             prompt: existingSection?.prompt,
  90             rules: existingSection?.rules ? [...existingSection.rules] : [],
  91             guidelines: existingSection?.guidelines ? [...existingSection.guidelines] : [],
  92             constraints: existingSection?.constraints ? [...existingSection.constraints] : [],
  93             behaviors: existingSection?.behaviors ? [...existingSection.behaviors] : [],
  94             context: existingSection?.context,
  95         });
  96         if (existingSection) usedIds.add(existingSection.id);
  97       }
  98     } else if (node.type === 'list' && currentChapter && isToc) {
  99         for (const listItem of node.children) {
 100             if (listItem.type === 'listItem') {
 101                 const sectionTitle = getNodeText(listItem).trim();
 102                 if (sectionTitle) {
 103                     flushSection();
 104                     const existingSection = findExistingItem(sectionTitle, existingContent, Section);
 105                     currentSection = new Section({
 106                         id: existingSection?.id,
 107                         title: sectionTitle,
 108                         type: 'report',
 109                         // Carry over other properties from existing if needed
 110                     });
 111                     if (existingSection) usedIds.add(existingSection.id);
 112                     flushSection();
 113                     currentSection = null;
 114                 }
 115             }
 116         }
 117     } else {
 118       if (currentSection) {
 119         accumulatedContent.push(node);
 120       }
 121     }
 122   }
 123 
 124   flushChapter();
 125 
 126   return newContent;
 127 }
