  10     const { project, updateProject } = useBuilderStore();
  11 
  12     const section = useMemo(() => project?.getSection(itemKey), [project, itemKey]);
  13 
  14     // This hook no longer uses local state that needs to be synced.
  15     // It directly calls the global `updateProject` function for immutability and consistency.
  16     // This prevents race conditions and simplifies the data flow.
  17 
  18     const setPrompt = (prompt: string) => {
  19         updateProject(currentProject => currentProject.updateSection(itemKey, section => section.with({ prompt })));
  20     };
  21 
  22     const setRules = (rules: string[]) => {
  23         updateProject(currentProject => currentProject.updateSection(itemKey, section => section.with({ rules })));
  24     };
  25 
  26     const setGuidelines = (guidelines: string[]) => {
  27         updateProject(currentProject => currentProject.updateSection(itemKey, section => section.with({ guidelines })));
  28     };
  29 
  30     const setConstraints = (constraints: string[]) => {
  31         updateProject(currentProject => currentProject.updateSection(itemKey, section => section.with({ constraints })));
  32     };
  33 
  34     const setBehaviors = (behaviors: Behavior[]) => {
  35         updateProject(currentProject => currentProject.updateSection(itemKey, section => section.with({ behaviors })));
